-- Insert into intl_rate_card via cross-join
INSERT INTO public.intl_rate_card (
  country_code, country_name, service_type,
  weight_min_kg, weight_max_kg, rate_inr, is_active
)
SELECT
  zm.country_code, zm.country_name, zr.service_type,
  zr.weight_min_kg, zr.weight_max_kg, zr.rate_inr, true
FROM _zone_map zm
JOIN _zone_rates zr ON zm.zone_code = zr.zone_code;

COMMIT;
